function v6SearchHandoff(toolId){const p=modalData,rows=libSearchRows(),ids=p.selected.filter(id=>rows.some(r=>r.id===id)&&auditFileAccess(file(id)).read),accepted=ids.filter(id=>auditFileAccess(file(id)).analyze&&!libEligible(file(id),toolId)),excluded=ids.filter(id=>!accepted.includes(id)).map(id=>({doc:file(id),reason:!auditFileAccess(file(id)).analyze?(libReady(file(id))?'当前资料无分析权限':libStatus(file(id))):libEligible(file(id),toolId)}));if(!ids.length)return v6Deny('请先勾选需要带入分析的文件。');if(excluded.length){openModal('lib-tool-handoff',{toolId,accepted:v6Canonical(accepted),excluded,searchReturn:p,scopeOrigin:'text-search'});return;}v6StopSearch(p);closeModal();libHandoff(toolId,v6Canonical(accepted));}
