 more.innerHTML='<summary class="btn sm" aria-label="更多资料操作">更多'+I('down','icon-sm')+'</summary><div class="lib-menu lib-overflow-panel"><div class="lib-overflow-filters" hidden><div class="lib-menu-label">查找与筛选</div><div class="lib-overflow-filter-fields"></div></div><section class="lib-batch-actions" aria-label="所选资料操作"><div class="lib-menu-label">'+(selected.length?'所选资料 · '+selected.length+' 份':'勾选资料后可批量操作')+'</div>'+B(I('fileMove','icon-sm')+'移动所选资料','lib-move-selected','ghost sm',allMove?'':'disabled title="请先勾选具有移动权限的资料"')+B(I('fileParse','icon-sm')+'重新解析','lib-reparse','ghost sm',reparse.length?'':'disabled title="所选资料中没有可重新解析的文件"')+B(I('trash','icon-sm')+'删除所选资料','lib-delete-selected','ghost danger sm',allDelete?'':'disabled title="请先勾选具有删除权限的资料"')+'</section><section class="lib-view-actions"><div class="lib-menu-label">目录与界面</div>'+B(I('accessKey','icon-sm')+'目录权限与说明','v6-access','ghost sm',access.read?'':'disabled')+B(I('toolbox','icon-sm')+(libraryPrefs.showTools?'收起分析工具':'展开分析工具'),'lib-toggle-tools','ghost sm')+'</section></div>';
