 const fileActions={'file-detail':'read','lib-attachments':'read','source':'preview','lib-download':'download','lib-rename-file':'rename','lib-delete-file':'delete','lib-move-file':'move','lib-pick-attachment':'attachments','lib-record-retry-one':'parse','retry-upload':'parse'};
 if(fileActions[action]&&id&&!v6GuardDocument(id,fileActions[action]))return;
