closeModal=function(){if(modal==='lib-revoke-confirm'){openModal(auditFolderAccess(modalData.space,modalData.path).grant?'lib-permissions':'v6-access',v6Context());return;}if(modal==='picker'&&modalData.v6TextSearch&&v6PickerBack){const back=v6PickerBack;v6PickerBack=null;openModal('lib-search',back);return;}if(modal==='lib-tool-handoff'&&modalData.scopeOrigin==='text-search'){openModal('lib-search',modalData.searchReturn);return;}if(modal==='lib-search')v6StopSearch(modalData);libraryV6Base.closeModal();if(modal==='lib-search')v6ScrollMatch();};
// New capture listeners run before legacy document listeners, preventing unauthorized callbacks as well as disabled UI.
window.addEventListener('change',e=>{const el=e.target,k=el.dataset.v6Change;if(k){e.stopImmediatePropagation();if(['grant-type','grant-level'].includes(k)){modalData[k==='grant-type'?'granteeType':'grantLevel']=el.value;paintModal();return;}if(k==='regex'||k==='case'){v6StopSearch(modalData);modalData[k==='regex'?'regex':'caseSensitive']=el.checked;modalData.hits=null;modalData.selected=[];modalData.preview=modalData.ids[0];paintModal();return;}if(k==='view-mode'){modalData.sourceMode=el.value;paintModal();v6ScrollMatch();return;}if(k==='search-check'){const valid=libSearchRows().some(r=>r.id===el.dataset.id)&&auditFileAccess(file(el.dataset.id)).read;if(valid)modalData.selected=el.checked?[...new Set([...modalData.selected,el.dataset.id])]:modalData.selected.filter(id=>id!==el.dataset.id);paintModal();return;}if(k==='search-all'){modalData.selected=el.checked?libSearchRows().map(r=>r.id):[];paintModal();return;}if(k==='search-tool'&&el.value)v6SearchHandoff(el.value);return;}
 if(el.dataset.change==='picker-check'&&el.checked&&!auditFileAccess(file(el.dataset.id)).read){e.stopImmediatePropagation();el.checked=false;v6Deny('此资料没有查看权限。');return;}if(el.dataset.libChange==='check'&&el.checked&&!auditFileAccess(file(el.dataset.id)).read){e.stopImmediatePropagation();el.checked=false;v6Deny('此资料没有查看权限。');}
},true);
window.addEventListener('keydown',e=>{if(modal!=='lib-search'||e.isComposing||/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName))return;if(['ArrowDown','ArrowUp'].includes(e.key)){const rows=libSearchRows();if(!rows.length)return;e.preventDefault();e.stopImmediatePropagation();let index=rows.findIndex(r=>r.id===modalData.preview);index=(index+(e.key==='ArrowDown'?1:-1)+rows.length)%rows.length;modalData.preview=rows[index].id;modalData.matchIndex=0;paintModal();v6ScrollMatch();}},true);
const v6RecordRows=libRecordRows;
