window.addEventListener('input',e=>{if(modal!=='lib-search'||e.target.id!=='lib-text-query')return;const p=modalData;p.keyword=e.target.value;let notice=$('.v6-keyword-notice');if(p.hits!==null&&p.keyword!==p.executedKeyword){if(!notice){notice=document.createElement('div');notice.className='v6-search-notice v6-keyword-notice';$('.v6-search-command')?.insertAdjacentElement('afterend',notice);}notice.textContent='检索词已修改，当前显示“'+p.executedKeyword+'”的结果，请重新检索。';}else notice?.remove();},true);
